Exercici 12.17 Donada la variable global (on N és una constant):


C

int v[N];

Calcula el temps d’execució en cicles de rellotge de cada versió del programa que suma els elements de v, suposant que:

Els accessos a memòria triguen 4 cicles.
Els salts que no salten triguen 1 cicle.
Els salts que salten triguen 2 cicles.
La resta d’instruccions triguen 1 cicle.






RV32I

        li    t0, 0          # suma
        li    t1, 0          # i
        li    t2, 0          # offset
bucle:
        li    t3, N
        bge   t1, t3, fi
        la    t4, v
        add   t4, t4, t2
        lw    t4, 0(t4)
        add   t0, t0, t4
        addi  t2, t2, 4
        addi  t1, t1, 1
        j     bucle
fi:






RV32I

        li    t0, 0          # suma
        li    t1, 0          # i
bucle:
        li    t3, N
        bge   t1, t3, fi
        la    t3, v
        slli  t2, t1, 2
        add   t2, t3, t2
        lw    t2, 0(t2)
        add   t0, t0, t2
        addi  t1, t1, 1
        j     bucle
fi:






RV32I

        li    t0, 0          # suma
        li    t1, 0          # i
bucle:
        la    t3, v
        slli  t2, t1, 2
        add   t2, t2, t3
        lw    t2, 0(t2)
        add   t0, t0, t2
        addi  t1, t1, 1
        li    t3, N
        blt   t1, t3, bucle






RV32I

        li    t0, 0          # suma
        li    t1, N-1        # i
bucle:
        la    t3, v
        slli  t2, t1, 2
        add   t2, t3, t2
        lw    t2, 0(t2)
        add   t0, t0, t2
        addi  t1, t1, -1
        bge   t1, zero, bucle






RV32I

        li    t0, 0          # suma
        li    t1, N          # i
        la    t2, v
bucle:
        lw    t3, 0(t2)
        add   t0, t0, t3
        addi  t2, t2, 4
        addi  t1, t1, -1
        bne   t1, zero, bucle


